import{_ as t,o as r,c as o,a5 as d}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"Redirect 路由","description":"这个 redirect 路由主要是一个 中转跳转页 ，在大厂项目里很常见，作用和场景大概有这几个： 1. 登录回跳 当用户访问某个需要登录的页面时，你会把他重定向到 /user?redirect /xxx 。 登录完成后，会跳到 /redirect?to /xxx 。 redir。","frontmatter":{"title":"Redirect 路由","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"这个 redirect 路由主要是一个 中转跳转页 ，在大厂项目里很常见，作用和场景大概有这几个： 1. 登录回跳 当用户访问某个需要登录的页面时，你会把他重定向到 /user?redirect /xxx 。 登录完成后，会跳到 /redirect?to /xxx 。 redir。","sidebarWeight":10,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/Redirect 路由/Redirect 路由.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/Redirect 路由/Redirect 路由.md","filePath":"posts/Vue系统教程/04-路由与状态管理/Redirect 路由/Redirect 路由.md"}'),i={name:"posts/Vue系统教程/04-路由与状态管理/Redirect 路由/Redirect 路由.md"};function c(a,e,s,l,n,u){return r(),o("div",null,[...e[0]||(e[0]=[d('<div><h1 id="redirect-路由" tabindex="-1">Redirect 路由 <a class="header-anchor" href="#redirect-路由" aria-label="Permalink to &quot;Redirect 路由&quot;">​</a></h1><blockquote><p>本节目标：理解“Redirect 路由”的核心思路，并能把它用于实际开发或面试表达。 这个 <code>redirect</code> 路由主要是一个 <strong><strong>中转跳转页</strong></strong>，在大厂项目里很常见，作用和场景大概有这几个：</p></blockquote><h3 id="_1-登录回跳" tabindex="-1">1. 登录回跳 <a class="header-anchor" href="#_1-登录回跳" aria-label="Permalink to &quot;1. 登录回跳&quot;">​</a></h3><ul><li>当用户访问某个需要登录的页面时，你会把他重定向到 <code>/user?redirect=/xxx</code>。</li><li>登录完成后，会跳到 <code>/redirect?to=/xxx</code>。</li><li><code>redirect</code> 页内部逻辑就是：读取 query 参数 <code>to</code>，然后用 <code>router.replace</code> 去真正的目标页面。</li><li>这样可以避免「登录守卫」和 <code>next({ path: ... })</code> 里出现多层嵌套跳转的问题。</li></ul><h3 id="_2-处理外链-动态跳转" tabindex="-1">2. 处理外链/动态跳转 <a class="header-anchor" href="#_2-处理外链-动态跳转" aria-label="Permalink to &quot;2. 处理外链/动态跳转&quot;">​</a></h3><ul><li>有时需要根据参数跳转到站内/外的不同页面，比如： <code>/redirect?to=https%3A%2F%2Fexample.com</code> → 最终会 <code>window.location.href</code> 到外部。</li><li>可以在这页里做统一处理（白名单校验 / 埋点统计）。</li></ul><h3 id="_3-清理多余状态" tabindex="-1">3. 清理多余状态 <a class="header-anchor" href="#_3-清理多余状态" aria-label="Permalink to &quot;3. 清理多余状态&quot;">​</a></h3><ul><li>一些场景下（比如登录态切换、刷新 token），需要「中间页」来清理缓存，再跳到目标地址。</li><li>例如退出登录后跳 <code>/redirect?to=/user</code>，先清理 token，再跳转。</li></ul><h3 id="_4-ssr-异步数据场景下的兜底" tabindex="-1">4. SSR / 异步数据场景下的兜底 <a class="header-anchor" href="#_4-ssr-异步数据场景下的兜底" aria-label="Permalink to &quot;4. SSR / 异步数据场景下的兜底&quot;">​</a></h3><ul><li>在 Next.js/Nuxt 等框架里会有 <code>/_redirect</code> 这种机制。</li><li>Vue 项目里模仿一个 <code>redirect</code> 页，保证跳转行为一致可控。</li></ul><p>✅ 总结一句： <code>redirect</code> 路由本身不会展示 UI，而是一个 <strong><strong>通用跳板页</strong></strong>，专门负责「安全可控的跳转」，常用于 <strong><strong>登录回跳</strong></strong>、<strong><strong>外链处理</strong></strong>、<strong><strong>状态清理</strong></strong>。</p></div>',1)])])}const x=t(i,[["render",c]]);export{h as __pageData,x as default};
